const ZSDumpTypeInfo *zs_dump_type_registry(void) { return kZSDumpTypes; }
NSUInteger zs_dump_type_count(void) { return sizeof(kZSDumpTypes) / sizeof(kZSDumpTypes[0]); }
NSUInteger zs_dump_type_count_for_category(NSInteger categoryIndex) {
    if (categoryIndex < 1 || categoryIndex > 9) return 0;
    char prefix[4]; snprintf(prefix, sizeof(prefix), "%ld.", (long)categoryIndex);
    NSUInteger c=0; for (NSUInteger i=0;i<zs_dump_type_count();i++) if (strncmp(kZSDumpTypes[i].category,prefix,strlen(prefix))==0) c++; return c;
}
BOOL zs_dump_registry_contains(NSString *assembly, NSString *namespaze, NSString *name) {
